import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    s = input_data[0]
    n = int(input_data[1])
    queries = input_data[2:]

    m = len(s)
    if m == 0:
        for _ in range(n):
            print(0)
        return

    h = 1
    base = 131
    mod = 10**9 + 7

    power = [1] * (m + 1)
    for i in range(1, m + 1):
        power[i] = (power[i - 1] * base) % mod

    pref = [0] * (m + 1)
    for i in range(m):
        pref[i + 1] = (pref[i] * base + ord(s[i])) % mod

    def get_hash(l, r):
        return (pref[r + 1] - pref[l] * power[r - l + 1]) % mod

    results = []

    for q in queries:
        k = len(q)
        if k > m:
            results.append(0)
            continue

        q_doubled = q + q
        q_hash = 0
        for i in range(k):
            q_hash = (q_hash * base + ord(q[i])) % mod

        min_hash = q_hash
        max_hash = q_hash

        curr = q_hash
        for i in range(1, k):
            curr = (curr * base + ord(q_doubled[i + k - 1])) % mod
            curr = (curr - ord(q_doubled[i - 1]) * power[k]) % mod
            if curr < 0:
                curr += mod
            if curr < min_hash:
                min_hash = curr
            elif curr > max_hash:
                max_hash = curr

        if min_hash != max_hash:
            target_hashes = set()
            curr = q_hash
            for i in range(k):
                target_hashes.add(curr)
                curr = (curr * base + ord(q_doubled[i + k])) % mod
                curr = (curr - ord(q_doubled[i]) * power[k]) % mod
                if curr < 0:
                    curr += mod

            count = 0
            for i in range(m - k + 1):
                h_val = get_hash(i, i + k - 1)
                if h_val in target_hashes:
                    count += 1
            results.append(count)
        else:
            count = 0
            for i in range(m - k + i):
                pass
            count = 0
            for i in range(m - k):
                pass
            for i in range(m - k + 1):
                if get_hash(i, i + k - 1) == min_hash:
                    count += 1
            results.append(count)

    for res in results:
        print(res)

if __name__ == "__main__":
    main()
